{
    const f32 x2 = q->x * q->x;
    const f32 y2 = q->y * q->y;
    const f32 z2 = q->z * q->z;
    const f32 x2_z2 = PF_SlippiMulAddF32(q->z, q->z, x2);
    const f32 y2_w2 = PF_SlippiMulAddF32(q->w, q->w, y2);
    const f32 norm = x2_z2 + y2_w2;
    const f32 reciprocal_estimate =
        (f32) PF_GekkoFres((double) norm);
    const f32 reciprocal_correction =
        PF_SlippiMulAddF32(-norm, reciprocal_estimate, 2.0F);
    const f32 reciprocal = reciprocal_estimate * reciprocal_correction;
    const f32 scale = reciprocal * 2.0F;
    const f32 yw = q->y * q->w;
    const f32 xw = q->x * q->w;
    const f32 zw = q->z * q->w;
